// The Crownwright logo, reproduced from the supplied animated SVGs
// (.attachments/crownwright-logo-animated-{light,dark,transparent-for-dark}.svg).
// The three files share the same artwork and differ only in the canvas,
// wordmark gradient, glow and tagline colours. Here those colours come from
// CSS variables (--logo-* in globals.css), so the one inline logo always
// shows the light artwork in the light theme and the dark artwork in the
// dark theme, including after the visitor uses the theme toggle.
//
// One logo serves both the company and the Crown AI tool (unified branding).

type Props = {
  /** "full" = badge + wordmark + tagline, "mark" = crown badge only. */
  variant?: "full" | "mark";
  /** Follow the active theme, or pin one of the official versions. */
  tone?: "auto" | "light" | "dark";
  /** Draw the logo's own canvas (the non-transparent light/dark files). */
  framed?: boolean;
  /** Rendered height in px; width follows the artwork's aspect ratio. */
  height?: number;
  animated?: boolean;
  className?: string;
  /** Decorative when a visible brand name is right next to it. */
  decorative?: boolean;
};

