// Cropped to the artwork (the source canvas is 816x304 with wide padding),
// so the logo sits flush in headers. `framed` keeps the original canvas.
const VIEWBOX = {
  full: { x: 36, y: 36, w: 724, h: 220 },
  mark: { x: 36, y: 36, w: 240, h: 220 },
  framed: { x: 0, y: 0, w: 816, h: 304 },
};

export default function Logo({
  variant = "full",
  tone = "auto",
  framed = false,
  height = 40,
  animated = true,
  className = "",
  decorative = false,
}: Props) {
  // Gradient/filter ids must be unique per instance (header + footer + ...).
  const uid = "cw" + useId().replace(/[^a-zA-Z0-9_-]/g, "");
  const box = framed ? VIEWBOX.framed : VIEWBOX[variant];
  const width = Math.round((height * box.w) / box.h);
  const showWordmark = variant === "full" || framed;
  const label = `${BRAND_NAME} — ${BRAND_TAGLINE}`;

  const classes = [
    "cw-logo",
    tone === "light" ? "cw-force-light" : tone === "dark" ? "cw-force-dark" : "",
    animated ? "" : "cw-static",
    className,
  ]
    .filter(Boolean)
    .join(" ");

  return (
    <svg
      xmlns="http://www.w3.org/2000/svg"
      viewBox={`${box.x} ${box.y} ${box.w} ${box.h}`}
      width={width}
      height={height}
      className={classes}
      data-tone={tone}
      {...(decorative ? { "aria-hidden": true, focusable: "false" } : { role: "img", "aria-label": label })}
    >
      {!decorative && <title>{label}</title>}
      <defs>
        <linearGradient id={`${uid}-bg`} x1="0" y1="0" x2="1" y2="1">
          <stop offset="0" stopColor="#FCD34D" />
          <stop offset=".5" stopColor="#EAB308" />
          <stop offset="1" stopColor="#D97706" />
        </linearGradient>
        <linearGradient id={`${uid}-wg`} gradientUnits="userSpaceOnUse" x1="0" y1="0" x2="478.1" y2="0">
          <stop offset="0" className="cw-wg-edge" />
          <stop offset=".5" className="cw-wg-mid" />
          <stop offset="1" className="cw-wg-edge" />
        </linearGradient>
        <linearGradient id={`${uid}-shine`} x1="0" y1="0" x2="1" y2="0">
          <stop offset="0" stopColor="#fff" stopOpacity="0" />
          <stop offset=".5" stopColor="#fff" stopOpacity=".75" />
          <stop offset="1" stopColor="#fff" stopOpacity="0" />
        </linearGradient>
        <filter id={`${uid}-halo`} x="-60%" y="-60%" width="220%" height="220%">
          <feGaussianBlur stdDeviation="26" />
        </filter>
        <filter id={`${uid}-soft`} x="-30%" y="-30%" width="160%" height="160%">
          <feGaussianBlur stdDeviation="5" />
        </filter>
        <filter id={`${uid}-spark`} x="-100%" y="-100%" width="300%" height="300%">
          <feGaussianBlur stdDeviation="3" />
        </filter>
        <clipPath id={`${uid}-bc`}>
          <rect x="64" y="64" width="176" height="176" rx="48" />
        </clipPath>
      </defs>

      {framed && <rect className="cw-bg" width="816" height="304" />}

      {/* Crown badge */}
      <rect className="cw-hl" x="64" y="64" width="176" height="176" rx="48" fill="#F5BE32" filter={`url(#${uid}-halo)`} />
      <rect x="60" y="60" width="184" height="184" rx="52" fill="none" stroke="#FDE68A" strokeOpacity=".8" strokeWidth="8" />
      <rect x="64" y="64" width="176" height="176" rx="48" fill={`url(#${uid}-bg)`} />
      <g clipPath={`url(#${uid}-bc)`}>
        <rect
          className="cw-sw"
          x="64"
          y="44"
          width="70"
          height="216"
          fill={`url(#${uid}-shine)`}
          transform="skewX(-18)"
          style={{ transformBox: "fill-box" }}
        />
      </g>
      <g className="cw-cr">
        <g
          transform="translate(112.0 112.0) scale(3.3333)"
          fill="none"
          stroke="#451A03"
          strokeWidth="2.25"
          strokeLinecap="round"
          strokeLinejoin="round"
        >
          <path d="M11.562 3.266a.5.5 0 0 1 .876 0L15.39 8.87a1 1 0 0 0 1.516.294L21.183 5.5a.5.5 0 0 1 .798.519l-2.834 10.246a1 1 0 0 1-.956.734H5.81a1 1 0 0 1-.957-.734L2.02 6.02a.5.5 0 0 1 .798-.519l4.276 3.664a1 1 0 0 0 1.516-.294z" />
          <path d="M5 21h14" />
        </g>
      </g>
      <circle className="cw-hl" cx="228.0" cy="76.0" r="34" fill="#FFFFFF" filter={`url(#${uid}-halo)`} />
      <g className="cw-gem">
        <g
          transform="translate(200.0 48.0) scale(2.3333)"
          fill="#FFFFFF"
          stroke="#FFFFFF"
          strokeWidth="2.5"
          strokeLinecap="round"
          strokeLinejoin="round"
        >
          <path d="M6 3h12l4 6-10 13L2 9Z" />
          <path d="M11 3 8 9l4 13 4-13-3-6" />
          <path d="M2 9h20" />
        </g>
      </g>
      <g transform="translate(228.0 76.0)">
        <path className="cw-st" d={SPARK} fill="#FFFFFF" filter={`url(#${uid}-spark)`} />
        <path className="cw-st" d={SPARK} fill="#FFFFFF" />
      </g>
      <g transform="translate(258.0 110.0) scale(.45)">
        <path className="cw-st cw-st2" d={SPARK} fill="#FFFFFF" />
      </g>

      {showWordmark && (
        <>
          <g transform="translate(274 150.0)">
            {LETTERS.map((d, i) => {
              const delay = { animationDelay: `${(0.45 + i * 0.17).toFixed(2)}s` };
              return (
                <g key={i}>
                  <g className="cw-b" style={delay}>
                    <path d={d} fill={`url(#${uid}-wg)`} />
                    <path className="cw-g cw-glow-fill" d={d} filter={`url(#${uid}-soft)`} style={delay} />
                    <path className="cw-l cw-lit-fill" d={d} style={delay} />
                  </g>
                </g>
              );
            })}
          </g>
          <path className="cw-tagline" transform="translate(274 204.0)" d={TAGLINE} />
        </>
      )}
    </svg>
  );
}
